\begin{assumption}[Regularity Conditions]\label{assumption_of_action_set_additional}

$\Acal$ and $\varepsilon$ must satisfy the following.
\begin{enumerate}[leftmargin=*,label=(\alph*)]
    \item There exists a $\lambda_C > 0$ such that 
    $\lambda_{n-1}(\nabla a^\star(\theta)) \geq \lambda_C$     
    for all $\theta \in \Theta$.

\item The eigenvalues $\{\lambda(\theta)\}_{i = 1}^n$ and the corresponding eigenvectors $\{u(\theta)\}_{i = 1}^n$ of $\nabla a^\star(\theta)$ can be selected so that they define a differentiable function on $\Theta$. 

\item The probability density function $p$ of the noise process $\ve$ is such that 
\begin{align}
    \mathscr{I}_{\ve} := \E\left[ \left(p'/p\right)^2\right]
    \label{eq:I.eps}
\end{align}
is finite and positive.
\end{enumerate}
\end{assumption}
